// Builds the submission manuscript. Every result number is read from results/manuscript_numbers.json.
const fs = require('fs');
const path = require('path');
const {
  Document, Packer, Paragraph, TextRun, HeadingLevel, AlignmentType, Table, TableRow, TableCell,
  WidthType, BorderStyle, ShadingType, ImageRun, Footer, PageNumber, LineNumberRestartFormat,
  PageBreak, LevelFormat,
} = require('docx');

const REPO = process.argv[2];
const OUT = process.argv[3];
const N = JSON.parse(fs.readFileSync(path.join(REPO, 'results/manuscript_numbers.json')));
const FIG = (f) => fs.readFileSync(path.join(REPO, 'figures', f));

// ---------- number helpers ----------
const minus = (s) => s.replace(/^-/, '−');
const f = (x, d = 2) => minus(Number(x).toFixed(d));
const pct = (x, d = 0) => `${(100 * x).toFixed(d)}%`;
const s1row = (design, delay, model) => N.s1.rows.find(r => r.design === design && (design !== 'prequential' || r.delay_days === delay) && r.model === model);
const pre = (L, m) => s1row('prequential', L, m);
const frz = (m) => s1row('frozen_burn_in_model', null, m);
const retro = (m, k) => N.s1.retro[m][k];
const pc = (m, L) => N.s1.paired.find(r => r.model === m && r.contrast === `recall(L=0) - recall(L=${L})`);
const sm = (sc, L, p) => N.s2.summary.find(r => r.scenario === sc && r.delay === L && r.policy === p);
const bi = (sc, p, L) => N.s2.bias.find(r => r.scenario === sc && r.policy === p && r.delay === L);
const dc = (sc, p, L) => N.s2.decomposition.find(r => r.scenario === sc && r.policy === p && r.delay === L);
const pd = (sc, L, c) => N.s2.policy_diff.find(r => r.scenario === sc && r.delay === L && r.comparison === c);
const arl = (ch, p) => N.s2.arl.find(r => r.chart === ch && Math.abs(r.p - p) < 1e-9);
const rk = (sc, L, pen, rb) => N.s2.rankings.find(r => r.scenario === sc && r.delay === L && r.penalty === pen && r.rollback_cost === rb);
const POLS = ['WS', 'FX', 'AC', 'AE'];
const s3r = (L) => N.s3.rows.find(r => r.design === 'replay' && r.delay_days === L);
const s3f = N.s3.rows.find(r => r.design === 'frozen');
const rt3 = N.s3.meta.retrospective;
const p1 = (x) => `${(100 * x).toFixed(1)}%`;
const s3slips = [0, 1, 3, 7, 14].map(L => s3r(L).slip_thr);
const s3m = (v) => N.s3m.find(r => r.variant === v);
const MODS = ['model_hgb', 'model_rf', 'model_logit'];
const rng3 = (k) => [Math.min(...MODS.map(v => s3m(v)[k])), Math.max(...MODS.map(v => s3m(v)[k]))];
const ag = (ds, m, band) => N.age.find(r => r.dataset === ds && r.model === m && r.band === band);
const keep = (ds, m, rnd, flag) => flag ? (ag(ds, m, '7-14').value - rnd) / (ag(ds, m, '0-7').value - rnd) : (rnd - ag(ds, m, '7-14').value) / (rnd - ag(ds, m, '0-7').value);
const sel = (m) => N.sel.filter(r => r.method === m);
const selq = (q) => N.sel.filter(r => r.q === q);
const ct = (B, n, m) => N.cert.find(r => r.policy === 'AC' && r.B === B && r.n === n && r.method === m);
const on = (D, m) => N.s3o.find(r => r.delay_days === D && r.method === m);
const ex = (pol, L) => N.exp.find(r => r.policy === pol && r.delay === L);
const sdz = (ds, m, act) => N.seeds.filter(r => r.dataset === ds && r.model === m && r.action === act);
const lk = (ds, m, act) => N.leak.find(r => r.dataset === ds && r.model === m && r.action === act);
const rcf = (q, L) => N.rc.find(r => r.q_max === q && r.delay === L && r.penalty === 35 && r.rollback_cost === 6);
const feasMax = (q) => Math.max(-1, ...[0, 1, 2, 3, 4].filter(L => rcf(q, L).best_constrained));
const svv = (v) => N.sens.sim.find(r => r.variant === v);
const aoiAges = ['7-14', '14-21', '21-28', '28-42'].map(b => ag('AOI', 'hgb', b).value);
const SCN = { nominal: 'Nominal', moderate_shift: 'Moderate shift', severe_shift: 'Severe shift', high_defect: 'High defect' };
const meta2 = N.s2.meta;

// derived quantities quoted in text
const biasNS = ['nominal', 'severe_shift'].flatMap(sc => POLS.map(p => bi(sc, p, 3).bias));
const biasMin = Math.min(...biasNS), biasMax = Math.max(...biasNS);
const oosRatio = sm('severe_shift', 0, 'FX').mean_oos_periods / sm('severe_shift', 0, 'AC').mean_oos_periods;
const nAgree = Math.round(N.s2.agreement_rate * N.s2.n_cells);
const extraDefSevere = ['WS', 'AC', 'AE'].map(p => dc('severe_shift', p, 3).extra_defects);
const nomRel = POLS.map(p => bi('nominal', p, 3).rel_bias_pct);

// ---------- formatting helpers ----------
const FONT = 'Times New Roman';
const P = (children, opts = {}) => new Paragraph({ spacing: { after: 120, line: 360 }, alignment: AlignmentType.JUSTIFIED, ...opts, children: (Array.isArray(children) ? children : [children]).map(c => typeof c === 'string' ? new TextRun(c) : c) });
const T = (s, o = {}) => new TextRun({ text: s, ...o });
const I = (s) => new TextRun({ text: s, italics: true });
const B = (s) => new TextRun({ text: s, bold: true });
const H1 = (s) => new Paragraph({ heading: HeadingLevel.HEADING_1, children: [new TextRun(s)] });
const H2 = (s) => new Paragraph({ heading: HeadingLevel.HEADING_2, children: [new TextRun(s)] });
const HL = (s) => new TextRun({ text: s, highlight: 'yellow' });
const caption = (s) => new Paragraph({ spacing: { before: 60, after: 200 }, children: [new TextRun({ text: s, size: 20 })] });
const tcap = (bold, rest) => new Paragraph({ spacing: { before: 200, after: 80 }, keepNext: true, children: [new TextRun({ text: bold, bold: true, size: 20 }), new TextRun({ text: rest, size: 20 })] });
const note = (s) => new Paragraph({ spacing: { after: 200 }, children: [new TextRun({ text: s, size: 18, italics: true })] });

const border = { style: BorderStyle.SINGLE, size: 4, color: '808080' };
const none = { style: BorderStyle.NONE, size: 0, color: 'FFFFFF' };
function table(header, rows, widths) {
  const W = widths.reduce((a, b) => a + b, 0);
  const cell = (txt, i, hdr, last) => new TableCell({
    width: { size: widths[i], type: WidthType.DXA },
    borders: { top: hdr ? border : none, bottom: (hdr || last) ? border : none, left: none, right: none },
    shading: hdr ? { fill: 'F2F2F2', type: ShadingType.CLEAR } : undefined,
    margins: { top: 40, bottom: 40, left: 80, right: 80 },
    children: [new Paragraph({ keepNext: !last, keepLines: true, alignment: (i === 0 || String(txt).length > 24) ? AlignmentType.LEFT : AlignmentType.CENTER, children: [new TextRun({ text: String(txt), size: 18, bold: hdr })] })],
  });
  return new Table({
    width: { size: W, type: WidthType.DXA }, columnWidths: widths,
    rows: [new TableRow({ tableHeader: true, cantSplit: true, children: header.map((h, i) => cell(h, i, true, false)) }),
      ...rows.map((r, j) => new TableRow({ cantSplit: true, children: r.map((c, i) => cell(c, i, false, j === rows.length - 1)) }))],
  });
}
const img = (file, w, h) => new Paragraph({ alignment: AlignmentType.CENTER, spacing: { before: 120 }, keepNext: true, children: [new ImageRun({ type: 'png', data: FIG(file), transformation: { width: w, height: h } })] });

// ---------- content ----------
const r0 = (m) => pre(0, m), r14 = (m) => pre(14, m);
const title = 'Decision-time data quality in manufacturing: quantifying evaluation bias with deployment replays and statistical process control';

const rng_abs = (arr, k) => `${p1(Math.min(...arr.map(r => r[k])))}–${p1(Math.max(...arr.map(r => r[k])))}`;
const abstract = `Quality-prediction models and process-change decisions are usually evaluated on historical data that are accurate but were not available when decisions had to be made: random splits put same-period and later production into training, and simulations assume inspection results arrive at once. We treat this gap between retrospective and decision-time information as a data-quality problem and quantify the resulting evaluation bias with deployment replays on two production datasets and a simulation. On SECOM semiconductor data, a random forest flagging 10% of units caught ${f(retro('random_forest', 'recall_at_budget').mean)} of failures under random splitting but ${f(r0('random_forest').recall_at_budget)} in a time-ordered replay (random inspection: ${f(N.s1.budget)}). On ${N.s3.meta.n.toLocaleString('en-US')} automated-optical-inspection alarms from a Siemens electronics line, a release rule set for 1% slip, estimated at ${p1(rt3.slip_thr.mean)} by random splitting, realized ${p1(s3r(0).slip_thr)} and exceeded the target in ${s3r(0).weeks_slip_above_target} of ${s3r(0).weeks} weeks. Size-matched experiments traced the bias to same-week units on the inspection line and to later production on SECOM. A delay-aware online threshold moved slip towards the target but did not prevent weekly exceedances; with labels only from random audits of 10–20% of releases, slip was ${rng_abs([...selq(0.1), ...selq(0.2)], 'slip')}. In a simulation comparing heuristic rules with CUSUM and EWMA monitoring, a three-period report delay reduced net value by ${f(biasMin, 1)}–${f(biasMax, 1)} units for every policy in nominal and severe-shift scenarios and changed which policies met an exposure limit; a certified formula gives the maximum admissible reporting delay. A reporting protocol links these checks to the data-quality dimensions of timeliness, completeness, fitness for purpose and traceability.`;

const body = [];
const add = (...xs) => body.push(...xs);
const supp = [];
const addS = (...xs) => supp.push(...xs);

// 1 Introduction
add(H1('1. Introduction'));
add(P(`Quality engineering increasingly relies on predictive models built from in-line sensor and process data, and on data-driven rules for deploying, monitoring and reversing process changes (Weese et al. 2016; Zonnenshain and Kenett 2020; He et al. 2022; Tercan and Meisen 2022). The value of such models and rules is almost always estimated retrospectively: a model is trained and tested on historical records whose quality outcomes are all known, and a decision rule is simulated as if each inspection result were available in the period it was produced.`));
add(P(`This practice raises a data-quality question that is easy to overlook. The data may be accurate, yet still not be the right data for the evaluation. A historical archive contains every quality outcome, but at the moment a decision is made many of those outcomes do not yet exist for the decision maker. Final test follows wafer processing by days, metrology and failure-analysis queues add further delay, and field returns arrive months later. Some outcomes never arrive at all: an alarm released without manual inspection is usually never labelled. These are examples of what Hand (2020) calls dark data, data that we should have but do not. An evaluation that ignores when, and whether, quality outcomes become available uses information unavailable at decision time, which is a form of temporal leakage. The data-stream literature calls this the delayed-labelling setting and has shown that it changes the measured performance of online classifiers (Gama, Sebastião and Rodrigues 2009; Grzenda et al. 2020). In quality-engineering applications, however, the size of the effect on screening and on pilot–deploy–rollback decisions, the mechanisms that produce it and the tools to account for it are seldom examined.`));
add(P(`The quality-engineering community has recently argued that data quality deserves the same disciplined treatment as product quality. Redman and Hoerl (2023) observe that statistical work depends on high-quality data, yet statistical applications, quality-improvement projects and data science initiatives remain plagued by bad data, and Pham, Hoerl and Redman (2026) propose a data life-cycle model designed to bring proven quality-improvement methods, such as statistical process control, to data quality. The problem studied here adds a temporal dimension to this view. A historical dataset may record quality outcomes accurately and completely, yet those outcomes were not available, or never became available, when the original decisions were made. The discrepancy between retrospective and decision-time information is therefore a matter of timeliness and completeness rather than accuracy (Wang and Strong 1996), and it can make screening, monitoring and intervention policies look better than they are. This study makes that dimension measurable through time-respecting deployment replays, explicit feedback mechanisms and decision-oriented performance measures.`));
add(P(`This paper asks two practical questions. First, how much does evaluating a quality decision with information that would not have been available at decision time overstate its value? Such information includes later production mixed into training by a random split and immediate labels used in place of delayed ones. Second, does it change which option a quality engineer would choose? We answer them with three complementary studies. Study 1 replays the deployment of a screening model on real semiconductor data (SECOM) in timestamp order, under explicit label-release delays, and compares the result with the usual random-split estimate. Study 3 applies the same replay to ${N.s3.meta.n.toLocaleString('en-US')} automated-optical-inspection alarms from a Siemens electronics line (Pfab et al. 2024), where the decision is which alarms may skip manual inspection. Study 2 uses a controlled simulation, in which true defect rates are known, to compare heuristic decision rules with standard statistical process control (SPC) tools (a single acceptance-sampling plan, binomial CUSUM and EWMA monitoring) under identical actions, information and random streams, across report delays and cost ratios. Figure 1 summarizes the three studies, the evaluation designs applied to them and the decision tools that result.`));
add(img('fig1_study_design.png', 600, 333));
add(caption('Figure 1. Overview of the three studies, the evaluation designs applied to them and the resulting decision tools. Each design compares an evaluation that uses information unavailable at decision time (random splits or immediate results) with one that respects when labels become available.'));
add(P(`The contribution is applied rather than algorithmic. All the methods we use are established. What is new is an evaluation of how the availability of quality data at decision time changes conclusions about quality decisions, together with practical tools for respecting it. The paper makes five contributions:`));
const contrib = (t) => new Paragraph({ spacing: { after: 80, line: 360 }, indent: { left: 540, hanging: 360 }, alignment: AlignmentType.JUSTIFIED, children: [new TextRun(t)] });
add(contrib('(1) a deployment-replay procedure for screening and release decisions that records when each label becomes usable, applied to two production datasets;'));
add(contrib('(2) size-matched experiments that separate the sources of the gap between random-split and deployment performance;'));
add(contrib('(3) a decomposition of the delay effect in simulation into slower deployment and slower detection, with a check of whether delay alters policy rankings and the feasibility of quality constraints;'));
add(contrib('(4) two applied tools with stated assumptions and proofs adapted from existing results: a delay-aware online release threshold for slip, which also works with randomized audits when released alarms are otherwise never labelled, and a statistically certified reporting-latency requirement for an exposure limit;'));
add(contrib('(5) a short reporting protocol that quality engineers can apply to their own evaluations.'));
add(P(`Section 2 reviews related work. Sections 3 and 4 describe the studies, Section 5 reports results, Section 6 discusses implications and limitations, and Section 7 concludes.`));
add(H1('2. Background and related work'));
add(H2('2.1 Evaluating quality-prediction models over time'));
add(P(`Random cross-validation assumes exchangeable observations. When data are ordered in time and the process changes, it tends to give optimistic estimates, and time-ordered schemes are preferred (Bergmeir and Benítez 2012; Roberts et al. 2017; Cerqueira et al. 2020). Changes in the relationship between inputs and outcomes over time are studied as concept drift (Gama et al. 2014). Prequential evaluation, in which each observation is first predicted and later used for training, is the standard protocol for evolving data (Gama, Sebastião and Rodrigues 2009); Grzenda et al. (2020) extended it to the case in which true labels arrive after a delay and showed that ignoring the delay misstates performance. Because manufacturing failures are rare, ranking metrics should be read against the base rate, and precision–recall summaries are more informative than ROC curves alone (Davis and Goadrich 2006; Saito and Rehmsmeier 2015). The SECOM dataset (McCann and Johnston 2008) is a common benchmark for this setting; its documented baseline uses ten-fold cross-validation, which mixes early and late production. Working with Siemens automated-optical-inspection data, Pfab and Rothering (2025) reached a related conclusion for false-call reduction: common best-practice evaluation did not anticipate performance in later production, and they called for explicit analysis of temporal dynamics.`));
add(H2('2.2 Deployment and rollback as acceptance sampling and process monitoring'));
add(P(`The decisions studied in Study 2 map directly onto classical quality tools. Deciding whether a pilot is good enough to deploy is an acceptance-sampling problem (Schilling and Neubauer 2009), or, with a prior on the defect rate, a Bayesian demonstration test (Hamada et al. 2008). Deciding whether a deployed change has degraded and should be reversed is a monitoring problem. CUSUM charts (Page 1954), including the binomial and Bernoulli forms for proportions (Reynolds and Stoumbos 1999), and EWMA charts (Roberts 1959; Lucas and Saccucci 1990) are standard choices, usually designed through their average run length (ARL) (Montgomery 2020; Woodall 2000). Practical guidance for choosing CUSUM parameters for proportions is available (Bourke 2018), and Woodall (2017) discusses the gap between monitoring theory and practice that evaluations such as ours aim to narrow. Report delay adds a fixed lag to every run length; its consequence for the economics of a deploy–monitor–rollback cycle is the quantity we estimate.`));
add(H2('2.3 Decision-theoretic approaches'));
add(P(`Sequential inspection, value of information and integrated quality–maintenance–production planning have been studied with formal decision theory (DeGroot 2004; Memarzadeh and Pozzi 2016; Fauriat and Zio 2020; Tasias 2022). These approaches can compute optimal policies for a specified model. We do not propose an optimal policy; our question concerns how any policy, optimal or heuristic, should be evaluated when information arrives late.`));
add(H2('2.4 Gap addressed'));
add(P(`Delayed-label evaluation is established in data-stream mining, and SPC provides well-understood tools for deployment and rollback decisions. What is missing for quality practitioners is an assessment that brings the two together: how large the instantaneous-label overstatement is for screening and for deploy–monitor–rollback decisions, which mechanism drives it, and whether it changes the choice between standard SPC tools and ad hoc rules. The two studies below address these points with real and simulated data respectively.`));

// 3 Study 1
add(H1('3. Studies 1 and 3: deployment replays on production data'));
add(H2('3.1 Data'));
add(P(`SECOM contains 1,567 production units from a semiconductor line, each with 590 process measurements and a pass/fail label from in-house line testing, recorded between ${N.s1.ts_start} and ${N.s1.ts_end}; 104 units failed (6.6%). Many features have missing values. The dataset gives a timestamp for each unit but not the time at which its label became available. We therefore treat the label delay L as a scenario parameter, with L = 0, 1, 3, 7 and 14 days, spanning same-day line test to off-line failure analysis. These are scenarios, not measured reporting delays, so the results show the potential consequences of delay rather than its realized impact at the original factory.`));
add(H2('3.2 Deployment replay'));
add(P(`Units are sorted by timestamp. The first 40% (${N.s1.n_burn} units, up to ${N.s1.deploy_start}) form the initial labelled history. The remaining ${N.s1.n_deploy} units, including ${N.s1.fail_deploy} failures, are processed in ${N.s1.weeks} consecutive seven-day windows. At the start of each window the model is refitted on all earlier units whose label would have been released by then, that is, units with timestamp + L no later than the window start. The window's units are then scored, and the 10% with the highest predicted risk in that window are flagged for extra inspection. Flagging the top 10% of a week corresponds to a batch decision, such as disposition of a week's lots once processing is complete. For decisions made unit by unit as production arrives, scores of later units are not yet available, so Section 3.7 also evaluates a strictly causal version with thresholds fixed from earlier data. All preprocessing is fitted on the training units only: features that are entirely missing or constant are dropped, remaining missing values are imputed with the training median, and, for logistic regression, features are standardized. We use L2-penalized logistic regression (C = 0.1) and a random forest (Breiman 2001) with 200 trees and a minimum leaf size of 3, implemented in scikit-learn (Pedregosa et al. 2011). As a reference for the value of retraining, we also score the deployment period with a frozen model fitted once on the initial history.`));
add(H2('3.3 Retrospective benchmark'));
add(P(`To represent the evaluation an analyst would usually report, we repeat a stratified random 60/40 split 50 times on the full dataset, fit the same models on the 60% part, and apply the same 10% budget to the 40% part. We report the mean and the 2.5th and 97.5th percentiles across splits.`));
add(H2('3.4 Metrics and uncertainty'));
add(P(`The primary metric is recall at budget: the share of failures that fall in the flagged 10%. Random inspection has an expected recall equal to the budget, 0.10. We also report precision at budget and the pooled ROC-AUC over the deployment period. Because consecutive units are not independent, confidence intervals for the replay use a calendar-day block bootstrap with 2,000 resamples (Künsch 1989; Efron and Tibshirani 1993). Contrasts between delays are paired: each bootstrap resample uses the same days for both delays.`));

// 4 Study 2
add(H2('3.5 Study 3: false-call reduction on Siemens AOI data'));
add(P(`To test whether the Study 1 findings hold on larger and more recent production data, we applied the same replay to the automated-optical-inspection (AOI) data of Pfab et al. (2024). The data contain ${N.s3.meta.n.toLocaleString('en-US')} solder joints flagged by AOI on one surface-mount line over about 132 days; ${N.s3.meta.defects.toLocaleString('en-US')} (${p1(N.s3.meta.defect_rate)}) were confirmed as true defects at manual inspection and the rest are false calls. Each joint has five categorical and 70 numeric inspection features; timestamps are anonymized but preserve order and spacing. Before deployment every alarm is inspected manually, so the initial history is fully labelled at the start of deployment; afterwards, only labels released by each decision time are used. The decision is to release alarms predicted to be false calls without manual inspection. The quality risk is slip, the share of true defects released, and the benefit is volume reduction, the share of false calls released. We use a slip target of 1% as an illustrative requirement. Before each week, the model is fitted on the older 80% of the labelled history, and the release threshold is set on the most recent 20% as the highest score that keeps slip at or below 1% there; it is then applied to that week's alarms. We also report slip when the 40% of alarms with the lowest predicted risk are released (random release would give slip of 0.40); this is a batch decision, and Section 3.7 evaluates a causal counterpart. The 1%-slip rule is already causal. The model is histogram-based gradient boosting (scikit-learn, 200 iterations) fitted on all true defects and a random 20% of false calls. As in Study 1, the first 40% of alarms form the initial history, and the remaining ${s3r(0).n.toLocaleString('en-US')} alarms (${s3r(0).defects.toLocaleString('en-US')} true defects) are processed in ${s3r(0).weeks} weekly windows with label delays of 0, 1, 3, 7 and 14 days, together with a model frozen at the start of deployment. The retrospective benchmark uses ${N.s3.meta.repeats} repeated stratified random 60/40 splits, with the threshold set on a random 20% of the training part. Intervals use a calendar-day block bootstrap with 2,000 resamples, paired across delays.`));
add(P(`To check whether the result depends on the model or the threshold procedure, we repeated the replay with immediate labels using a class-weighted random forest (300 trees, minimum leaf size 5) and L2-penalized logistic regression on standardized numeric and one-hot categorical features, and with three alternative threshold procedures for the gradient-boosting scores: calibration on the most recent seven days of labelled history only; a 0.5% slip target; and a confidence-bound rule that chooses the largest threshold for which the one-sided 95% Clopper–Pearson upper bound on slip in the calibration data is at most 1% (Clopper and Pearson 1934). Each model's random-split estimate uses three repeated splits.`));
add(H2('3.6 Model ageing'));
add(P(`To explain when label delay matters, we measured how quickly models lose value with age on both datasets. At weekly anchors from the start of deployment, a model was fitted on all earlier units and applied to units 0–7, 7–14, 14–21, 21–28 and 28–42 days later. Within each anchor and age band we applied the main decision (SECOM: flag the top 10% with logistic regression or the random forest; AOI: release the 40% lowest-risk alarms with gradient boosting) and pooled outcomes over anchors by age band, with calendar-day block bootstrap intervals. A label delay of L days means the deployed model is always at least L days old, so a curve that falls steeply over the first weeks makes delay costly, whereas a flat curve makes it unimportant.`));
add(H2('3.7 Separating sources of the gap'));
add(P(`A gap between a random-split estimate and deployment performance can arise from several differences at once: the population evaluated, the amount of training data, the presence of units from the same period in both training and test data, and the use of later production for training. To separate them, for every weekly window of the replays (immediate labels) we evaluated three models on the same randomly chosen half of the window's units. A chronological model (C) was fitted on all earlier units. A size-matched model (M) was fitted on a random sample of the same size drawn from all units outside the window, earlier or later. A second size-matched model (W) used a sample that could also include the other half of the same window. C and M differ only in whether later production is used; M and W differ only in whether units from the same week are used. In each design, 20% of the training data (the most recent part for C, a random part otherwise) was held out to set thresholds; the calibration sets therefore differ in time as well as composition, which contributes to the contrasts for threshold-based decisions, whereas batch decisions and lift do not depend on the threshold. Decisions were evaluated in batch form (top 10% or lowest 40% of the evaluated units) and in strictly causal form, in which the threshold is the 90th (SECOM) or 40th (AOI) percentile of the held-out calibration scores and never uses scores from the window itself. Because the realized action rate of causal decisions varies, we also report lift: the share of failures acted on divided by the share of units acted on, which equals 1 for random selection (for AOI releases, lower is better). Intervals use a paired calendar-day block bootstrap with 2,000 resamples.`));
add(H2('3.8 Delay-aware online slip calibration'));
add(P(`The static 1%-slip threshold of Section 3.5 is reset each week from past labels and has no guarantee once the process drifts. As an alternative we adapt quantile tracking from adaptive conformal inference (Gibbs and Candès 2021; Angelopoulos, Candès and Tibshirani 2023) to the feedback structure of AOI release. An alarm is released if its score s, a clipped logit of the model output in (−b, b) with b = ${N.s3o_meta.b_clip}, is below a threshold θ. A true defect that is inspected is confirmed at once (e = 0); a released defect is discovered only after a delay of D days, for example at downstream test, in a field return or by audit (e = 1). Each confirmation updates θ ← θ + γ(α − e), with α = 0.01. The feedback is therefore action-dependent: only releases are delayed. θ starts at the static threshold of the initial history, and the weekly models are those of the replay with model-refit delay D. We evaluate D = 0, 1, 3 and 7 days and step sizes γ = 0.02, 0.05, 0.1 and 0.2 (logit units), fixed in advance, and compare with the static rule on identical scores.`));
add(P(`Proposition 1. Let M be the largest number of released defects awaiting confirmation at any time and K the number of confirmed defects. For every score sequence, |K⁻¹ Σₖ eₖ − α| ≤ (b + |θ₀| + γ(M + 1))/(γK). The proof (Appendix S1) bounds the threshold path; it follows the argument of Angelopoulos, Candès and Tibshirani (2023) and of Wang and Hyndman (2024), who give the corresponding bound for a fixed feedback delay h. The modest extension here is that the delay depends on the action and the in-flight count M takes the place of h. The guarantee concerns long-run average slip over all defects, not any week; it says nothing about volume reduction; and it requires every released defect to be discovered eventually (Section 3.9 relaxes this with randomized audits). The proof does not use the order in which confirmations arrive, so it covers variable, out-of-order and bursty delays; the constant γ(M + 1) can be tightened to γ·max(α, (1 − α)M), and convergence requires K → ∞ with M/K → 0. In 300 further adversarial runs with such delays and step sizes from 0.001 to 5, the deviation reached at most 0.98 of the bound, so the bound is nearly tight.`));
add(H2('3.9 Audited release under selective feedback'));
add(P(`In practice a released alarm may never be labelled. We therefore also evaluate a version in which released alarms are labelled only if audited after release, independently with probability q, and the threshold is updated with inverse-propensity weights (Horvitz and Thompson 1952). Proposition 3 (Appendix S2) bounds the realized slip over all defects with high probability, combining the threshold-path argument of Proposition 1 with Freedman's (1975) martingale inequality; without audits or other feedback, slip is not identifiable. The construction is close to adaptive conformal inference with intermittent feedback (Wang, Zecchin and Simeone 2025) and is offered as an applied extension. Appendix S2 also describes three further calibration baselines evaluated on identical scores and an observable finite-horizon bound (Corollary 1).`));
add(H1('4. Study 2: simulation with SPC comparators'));
add(H2('4.1 Process, information and actions'));
add(P(`Each simulated run lasts ${meta2.H} periods. In each period the line either runs a pilot or produces, and ${meta2.B} items are inspected. Items are defective independently with probability p, which may shift after period ${meta2.shift_period}. Table 1 lists the four scenarios. Inspection results for period t become usable at the start of period t + 1 + L, where the report delay L takes the values 0 to 4 periods. A production period is counted as out of specification when the true defect probability exceeds 0.12; this label is used only for evaluation and is never visible to a policy.`));
add(P(`All policies have the same actions: pilot (inspect a batch before deployment), deploy, produce, wait, abandon, and roll back. Abandon and roll back end the run. All policies observe exactly the same released results, and for a given random seed every policy and every delay uses the same item-level random stream (common random numbers; Law 2015), so differences between policies and between delays are paired.`));
add(tcap('Table 1. ', 'Simulation scenarios (defect probability before and after the shift at period 9).'));
add(table(['Scenario', 'p before shift', 'p after shift', 'Interpretation'], [
  ['Nominal', '0.035', '0.035', 'Good change, stable process'],
  ['Moderate shift', '0.035', '0.10', 'Degradation that stays within specification'],
  ['Severe shift', '0.035', '0.24', 'Degradation beyond the 0.12 specification'],
  ['High defect', '0.22', '0.22', 'Bad change from the start'],
], [2000, 1500, 1500, 4000]));
add(H2('4.2 Policies'));
add(P(`Table 2 defines the four policies. WS and FX are simple heuristic rules of the kind used when no formal plan is in place. AC and AE represent standard practice: a single acceptance-sampling plan (n = 40, c = 3) decides deployment, and a binomial CUSUM (AC) or an EWMA chart (AE) on released post-deployment batches decides rollback. The CUSUM is designed to detect a shift from 0.035 to 0.20. The EWMA uses λ = 0.2 with a three-sigma limit at 0.035. The two charts have similar in-control ARLs (Table S2). The acceptance plan accepts a process with p = 0.035 with probability ${f(meta2.acceptance_plan.P_accept['0.035'], 3)}, one with p = 0.12 with probability ${f(meta2.acceptance_plan.P_accept['0.120'], 3)}, and one with p = 0.24 with probability ${f(meta2.acceptance_plan.P_accept['0.240'], 3)}. Chart and plan parameters were set once, before the study, and were not tuned to the results.`));
add(tcap('Table 2. ', 'Policy definitions. All policies use only released inspection results.'));
add(table(['Policy', 'Deployment rule', 'Rollback rule'], [
  ['WS (Wilson-score heuristic)', 'Deploy when ≥ 40 items are released and the 95% Wilson upper bound (Wilson 1927) ≤ 0.18; abandon after ≥ 5 pilots if no report is pending', 'Cumulative released defect rate > 0.12'],
  ['FX (fixed two-pilot rule)', 'After two pilot batches and ≥ 40 released items, deploy if released rate ≤ 0.12, otherwise abandon', 'Cumulative released defect rate > 0.20'],
  ['AC (acceptance plan + CUSUM)', 'Single plan n = 40, c = 3 (pilot until 40 items are sampled, then wait for results)', 'Binomial CUSUM, p₀ = 0.035, p₁ = 0.20, h = 4.0'],
  ['AE (acceptance plan + EWMA)', 'As AC', 'EWMA of batch fraction defective, λ = 0.2, UCL = ' + f(meta2.ewma.ucl, 3)],
], [2300, 4200, 2500]));
add(H2('4.3 Economics'));
add(P(`A production period earns 8 units minus c_d times the period's fraction defective; a pilot costs 0.5, deployment 3, and rollback R. The defect penalty c_d takes the values 15, 35 and 70 and R the values 2, 6 and 18, giving nine cost pairs; the base case is c_d = 35, R = 6. Production breaks even when the fraction defective equals 8/c_d (0.23 in the base case). All amounts are normalized, illustrative units. Because no policy's decisions depend on costs, net value for every cost pair is computed exactly from the recorded counts of production periods, defects, pilots, deployments and rollbacks.`));
add(H2('4.4 Design and analysis'));
add(P(`We simulate ${meta2.seeds.toLocaleString('en-US')} seeds for each scenario, delay and policy (${meta2.trajectories.toLocaleString('en-US')} runs). The instantaneous-label overstatement for policy π and delay L is V_π(0) − V_π(L), the mean paired difference in net value between an evaluation that assumes immediate results and one that respects the delay. We decompose it into lost production revenue, additional defect cost, additional pilot cost, and deployment and rollback costs. Policy differences are paired by seed. All intervals are percentile intervals from 2,000 bootstrap resamples of seeds. To ask whether the delay changes the decision, we identify, for each scenario and cost pair, the policy with the highest mean value under immediate results and under each true delay. We report how often the two agree and the regret, defined as the value, under the true delay, lost by choosing the policy that looked best under immediate results.`));

// 5 Results
add(H2('4.5 Latency requirement for an exposure limit'));
add(P(`Proposition 2. Suppose that, whatever the report delay, the policy deploys in the same runs and before the shift, production continues until rollback or the horizon, the shift persists, and the monitoring statistic has the same value at the shift and receives the same post-shift batch outcomes. Then a delay of L periods postpones rollback by exactly L periods, so the out-of-specification exposure of a run is min(H, Z + L), where Z is its exposure under immediate results and H the number of post-shift periods. Consequently E(L) = E[D·min(H, Z + L)] and E(L + 1) − E(L) = P(D = 1, Z + L < H) ≤ 1, with D the deployment indicator, and the largest admissible delay for an exposure limit B is L_max(B) = max{L : E(L) ≤ B}; no delay is admissible if E(0) > B, and if every candidate delay satisfies the limit, L_max is reported only as at least the largest delay considered (proof in Appendix S1). The result is elementary; its use is practical, because L_max can be computed from runs or records under immediate feedback alone. We test the predicted E(L) against the simulated exposure for all four policies, which also shows where the assumption of an unchanged observation sequence fails.`));
add(H2('4.6 Certified latency requirement'));
add(P(`A plug-in estimate of L_max carries no statement of confidence. Under the assumptions of Proposition 2, each run's exposure is a nondecreasing bounded function of a single quantity, so one Dvoretzky–Kiefer–Wolfowitz confidence band (Dvoretzky, Kiefer and Wolfowitz 1956; Massart 1990) gives upper bounds on E(L) for all delays simultaneously (Corollary 2). We compare the resulting certified delay with plug-in, Bonferroni-corrected Hoeffding and empirical-Bernstein (Maurer and Pontil 2009) procedures in repeated samples (Appendix S2). The guarantee requires the assumptions of Proposition 2 and independent runs; where they are violated, as for the EWMA policy, coverage can only be checked empirically.`));
add(H1('5. Results'));
add(H2('5.1 Study 1: screening value on real data'));
const s1rows = [];
['logistic', 'random_forest'].forEach(m => {
  const nm = m === 'logistic' ? 'Logistic' : 'Random forest';
  const rr = retro(m, 'recall_at_budget'), ra = retro(m, 'roc_auc'), rp = retro(m, 'precision_at_budget');
  s1rows.push([`${nm}: random split (50 repeats)`, '—', `${f(rr.mean)} (${f(rr.p2_5)}–${f(rr.p97_5)})`, f(rp.mean), `${f(ra.mean)} (${f(ra.p2_5)}–${f(ra.p97_5)})`]);
  [0, 1, 3, 7, 14].forEach(L => { const r = pre(L, m); s1rows.push([`${nm}: replay`, `${L} d`, `${f(r.recall_at_budget)} (${f(r.recall_lo)}–${f(r.recall_hi)})`, f(r.precision_at_budget), `${f(r.pooled_roc_auc)} (${f(r.auc_lo)}–${f(r.auc_hi)})`]); });
  const z = frz(m); s1rows.push([`${nm}: frozen model`, '—', `${f(z.recall_at_budget)} (${f(z.recall_lo)}–${f(z.recall_hi)})`, f(z.precision_at_budget), `${f(z.pooled_roc_auc)} (${f(z.auc_lo)}–${f(z.auc_hi)})`]);
});
add(P(`Table 3 and Figure 2 summarize Study 1. The retrospective random-split evaluation suggested that a random forest flagging 10% of units would catch ${f(retro('random_forest', 'recall_at_budget').mean)} of failures, three times the rate of random inspection, with a ROC-AUC of ${f(retro('random_forest', 'roc_auc').mean)}. In the deployment replay with immediate labels, the same model caught ${f(r0('random_forest').recall_at_budget)} (95% CI ${f(r0('random_forest').recall_lo)}–${f(r0('random_forest').recall_hi)}), with a pooled ROC-AUC of ${f(r0('random_forest').pooled_roc_auc)}. Logistic regression caught ${f(r0('logistic').recall_at_budget)}, against a retrospective estimate of ${f(retro('logistic', 'recall_at_budget').mean)}. Even before any delay is introduced, then, respecting time order reduces the estimated screening value, most markedly for the random forest.`));
add(P(`Longer label delays were associated with lower screening value. At a 14-day delay the two models caught ${f(r14('logistic').recall_at_budget)} and ${f(r14('random_forest').recall_at_budget)} of failures, close to the 0.10 expected from random inspection, and the pooled ROC-AUC fell below 0.5 for both. The paired contrast between immediate and 14-day labels was ${f(pc('logistic', 14).estimate)} (95% CI ${f(pc('logistic', 14).lo)} to ${f(pc('logistic', 14).hi)}) for logistic regression and ${f(pc('random_forest', 14).estimate)} (${f(pc('random_forest', 14).lo)} to ${f(pc('random_forest', 14).hi)}) for the random forest. These intervals include zero: with ${N.s1.fail_deploy} failures spread over ${pc('logistic', 14).failure_days} days, the data are consistent with a substantial loss but cannot establish one. The frozen model, never retrained, caught ${f(frz('logistic').recall_at_budget)} (logistic) and ${f(frz('random_forest').recall_at_budget)} (random forest), which indicates that the screening value in this period depends on recent labels, and hence on how quickly they arrive.`));
add(tcap('Table 3. ', `SECOM screening with a 10% inspection budget. Replay: ${N.s1.n_deploy} units, ${N.s1.fail_deploy} failures, weekly refits on released labels. Intervals: day-block bootstrap (replay) or 2.5–97.5% range over splits (random split).`));
add(table(['Evaluation', 'Label delay', 'Recall at budget', 'Precision at budget', 'ROC-AUC'], s1rows, [3100, 1000, 1900, 1200, 1800]));
